#include <bits/stdc++.h>
using namespace std;

#define int long long

signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y;
    cin >> x >> y;

    vector<int> divisors;
    for (int i = 1; i <= x / i; ++i) {
        if (x % i == 0) {
            divisors.push_back(i);
            if (i != x / i)
                divisors.push_back(x / i);
        }
    }

    int ans = 0;

    while (y > 0) {
        int g = std::gcd(x, y);
        int current = y / g;
        int best = current;

        for (int divisor : divisors) {
            if (divisor > g && divisor % g == 0) {
                int factor = divisor / g;
                best = min(best, current % factor);
            }
        }

        ans += best;
        y -= best * g;
    }

    cout << ans << '\n';
    return 0;
}

