using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 x, y;
    cin >> x >> y;

    vector<int64> primes;
    int64 n = x;

    for (int64 p = 2; p <= n / p; ++p) {
        if (n % p == 0) {
            primes.push_back(p);
            while (n % p == 0) n /= p;
        }
    }
    if (n > 1) primes.push_back(n);

    int64 ans = 0;

    while (y > 0) {
        int64 g = gcd(x, y);
        int64 a = x / g;
        int64 b = y / g;
        int64 steps = b;

        for (int64 p : primes) {
            if (a % p == 0) {
                steps = min(steps, b % p);
            }
        }

        ans += steps;
        y -= steps * g;
    }

    cout << ans << '\n';
    return 0;
}

