            prime_factors.push_back(p);
            while (n % p == 0) n /= p;
        }
    }
    if (n > 1) prime_factors.push_back(n);

    int ans = 0;

    while (y > 0) {
        int g = gcd(x, y);
        int reduced_x = x / g;
        int reduced_y = y / g;

        if (reduced_x == 1) {
            ans += reduced_y;
            break;
        }

        int steps = reduced_y;
        for (int p : prime_factors) {
            if (reduced_x % p == 0) {
                steps = min(steps, reduced_y % p);
            }
        }

        ans += steps;
        y -= steps * g;
    }

    cout << ans << '\n';
    return 0;
}

