#include <bits/stdc++.h>
#include <ext/pb_ds/assoc_container.hpp>

using namespace std;
using namespace __gnu_pbds;

#define int long long

typedef tree<pair<int, int>, null_type, less<pair<int, int>>, rb_tree_tag,
             tree_order_statistics_node_update> ordered_set;

#define all(x) x.begin(), x.end()
#define pb push_back
#define fastio ios_base::sync_with_stdio(false), cin.tie(nullptr), cout.tie(nullptr)
#define sz(x) (int)x.size()

const int INF = 1e18;

signed main() {
    fastio;

    int x, y;
    cin >> x >> y;

    vector<int> divisors;
    for (int i = 1; i <= x / i; ++i) {
        if (x % i == 0) {
            divisors.pb(i);
            if (i != x / i)
                divisors.pb(x / i);
        }
    }

    sort(all(divisors));

    int ans = 0;

    while (y > 0) {
        int g = std::gcd(x, y);
        int best = INF;

        for (int d : divisors) {
            if (d > y)
                break;
            if (d <= g || d % g != 0)
                continue;

            best = min(best, (y % d) / g);
        }

        if (best == INF) {
            ans += y / g;
            break;
        }

        ans += best;
        y -= best * g;
    }

    cout << ans << '\n';
    return 0;
}

